-- Reference schema for the connected Supabase project.
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,class_seat text not null default '',display_name text,role text not null default 'student' check(role in('student','teacher')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.games(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,class_seat text not null default '',level int not null check(level between 1 and 3),started_at timestamptz not null default now(),finished_at timestamptz,final_time numeric,incorrect_attempts int not null default 0,penalty_time numeric not null default 0,rank int,status text not null default 'playing' check(status in('playing','finished','abandoned')),created_at timestamptz not null default now());
create table if not exists public.answers(id bigint generated by default as identity primary key,game_id uuid not null references public.games(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,class_seat text not null default '',level int not null check(level between 1 and 3),question_no int not null,question_type text,question jsonb,answer text,correct boolean not null default false,event_type text not null default 'answer',elapsed_ms bigint,incorrect_attempts int not null default 0,penalty_time numeric not null default 0,created_at timestamptz not null default now());
create table if not exists public.questions(id uuid primary key default gen_random_uuid(),level int not null check(level between 1 and 3),question_type text not null default 'equation',prompt jsonb not null,answer text not null,explanation jsonb,difficulty int not null default 1 check(difficulty between 1 and 5),is_active boolean not null default true,sort_order int not null default 0,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());

-- The live project also contains RLS policies, Auth trigger and reporting RPCs:
-- get_leaderboard, is_teacher, teacher_overview, student_performance, question_stats.
-- See Supabase migration history for the deployed definitions.
